mapper.select:
select a.REGIST_SEQNO registSeqno,
IFNULL(t2.pbc_code,a.PBC_PROD_ID) PBC_PROD_ID,
a.PBC_PROD_ID PBC_PROD_ID,
a.MDATE mdate, a.CCY ccy, a.PROFIT profit, a.PROFIT_CNY profitCny, a.CUSTOM_PROFIT customProfit, a.CUSTOM_PROFIT_CNY customProfitCny, a.CUS_YEAR_YIELD cusYearYield, a.SEND_STATUS sendStatus, a.SUBMIT_TIME submitTime, a.SUBMIT_FEEDBACK_STATUS submitFeedbackStatus, a.SUMIT_SEQ sumitSeq, a.STATUS_DATE statusDate, a.PBC_SUBMIT_DEADLINE pbcSubmitDeadline, a.SUBMIT_DEADLINE submitDeadline, a.STATUS status, a.CREATE_USER createUser, SI.INSTITUTION_CODE orgCode, a.CREATE_DEPT createDept, a.CREATE_TIME createTime, a.UPDATE_USER updateUser, a.UPDATE_TIME updateTime, b.PROD_ID prodId, b.OPERATE_MODE operateMode, b.IVSTORIENTATION ivstorientation, b.VDATE vdate, t2.PBC_CODE pbcCode, ifnull(t2.pbc_code,a.PBC_PROD_ID) pbcProdIdShow from PBC_PRD_BASEINFO_END_SUB a left join b on a.PBC_PROD_ID = b.PBC_PROD_ID
LEFT JOIN( SELECT inside_prod_id, pbc_code FROM pbc_prod_assetpool_code WHERE status='E' AND code_type='01' )t2 ON t2.inside_prod_id=b.PROD_ID LEFT JOIN CHB_ORG_REGIST_BANK_CODE CORBC ON CORBC.PBC_BANK_CODE = b.ISSUE_PARTY_ID LEFT JOIN SYS_INSTITUTION SI ON SI.INSTITUTION_CODE = CORBC.ORG_CODE
#{items,jdbcType=VARCHAR}
AND b.PROD_ID IN
#{item,jdbcType=VARCHAR}
and a.STATUS in
#{item,jdbcType=VARCHAR}
and trim(a.REGIST_SEQNO) in
#{item,jdbcType=VARCHAR}
and a.SEND_STATUS in
#{item,jdbcType=VARCHAR}
and a.SUBMIT_FEEDBACK_STATUS in
#{item,jdbcType=VARCHAR}
and b.OPERATE_MODE in
#{item,jdbcType=VARCHAR}
and b.IVSTORIENTATION in
#{item,jdbcType=VARCHAR}
and DATE_FORMAT(a.STATUS_DATE,'%Y-%m-%d') >= #{statusDateStart}
and DATE_FORMAT(a.STATUS_DATE,'%Y-%m-%d') <= #{statusDateEnd}
and DATE_FORMAT(a.SUBMIT_TIME,'%Y-%m-%d') >= #{submitTimeStart}
and DATE_FORMAT(a.SUBMIT_TIME,'%Y-%m-%d') <= #{submitTimeEnd}
and DATE_FORMAT(a.PBC_SUBMIT_DEADLINE,'%Y-%m-%d') >= #{pbcSubmitDeadlineDateStart}
and DATE_FORMAT(a.PBC_SUBMIT_DEADLINE,'%Y-%m-%d') <= #{pbcSubmitDeadlineDateEnd}
and DATE_FORMAT(a.MDATE,'%Y-%m-%d') >= #{mdateStart}
and DATE_FORMAT(a.MDATE,'%Y-%m-%d') <= #{mdateEnd}
and DATE_FORMAT(a.UPDATE_TIME,'%Y-%m-%d') = #{updateTime}
and DATE_FORMAT(a.MDATE,'%Y-%m-%d') >= #{startDate}
and DATE_FORMAT(a.MDATE,'%Y-%m-%d') <= #{endDate}
ORDER BY A.PBC_SUBMIT_DEADLINE ASC, A.UPDATE_TIME DESC

