insert into PBC_PRD_BASEINFO_END_SUB () select HIS_NO, PBC_PROD_ID, MDATE, CCY, PROFIT, PROFIT_CNY, CUSTOM_PROFIT, CUSTOM_PROFIT_CNY, CUS_YEAR_YIELD, SEND_STATUS, SUBMIT_TIME, SUBMIT_FEEDBACK_STATUS, SUMIT_SEQ, STATUS_DATE, PBC_SUBMIT_DEADLINE, SUBMIT_DEADLINE, STATUS, CREATE_USER, ORG_CODE, CREATE_DEPT, NOW(), UPDATE_USER, NOW() from ( select , rank() over (partition by PBC_PROD_ID order by ifnull(update_time,create_time) desc) ranknum from PBC_PRD_BASEINFO_END_SUB_HIS where PBC_PROD_ID in
#{item.pbcProdId,jdbcType=CHAR}
) as t where t.ranknum = 1

